INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    'MOCK',
    2026,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '基于 /Users/permer/Documents/408资料/26王道计算机408《八套卷》试卷题目.pdf 的卷一单选题知识点改写扩容。',
    'PLAIN_TEXT',
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000020001','DATA_STRUCTURE','DS_LINEAR_LIST','BASIC','下列选项中，通常不属于算法基本特征的是？','D','算法通常强调有穷性、确定性、可行性、输入和输出，可读性更多是程序书写质量要求。'),
    ('00000000-0000-0000-0000-000000020002','DATA_STRUCTURE','DS_TREE','MEDIUM','若某二叉树采用二叉链表存储，则 n 个结点共有多少个空指针域？','B','二叉链表共有 2n 个指针域，非空指针域为 n - 1，因此空指针域为 n + 1。'),
    ('00000000-0000-0000-0000-000000020003','DATA_STRUCTURE','DS_TREE','MEDIUM','给定互不相同关键字的二叉排序树，其前序序列必须满足什么约束？','C','二叉排序树前序序列中，根之后先出现小于根的左子树结点，再出现大于根的右子树结点，且左右子序列也递归满足该约束。'),
    ('00000000-0000-0000-0000-000000020004','DATA_STRUCTURE','DS_TREE','HARD','关于 B 树和 B+ 树，下列说法正确的是？','D','B 树结点可保存关键字和数据；B+ 树非叶结点通常只保存索引关键字，叶结点有序链接，适合范围查询，二者插入删除都可能调整结构。'),
    ('00000000-0000-0000-0000-000000020005','DATA_STRUCTURE','DS_SORT','BASIC','快速排序在划分最均衡时，平均时间复杂度通常为？','C','快速排序每趟划分需要线性扫描，若划分均衡，则递归深度为 log n，平均复杂度为 O(n log n)。'),
    ('00000000-0000-0000-0000-000000020006','DATA_STRUCTURE','DS_SORT','MEDIUM','下列排序算法中，通常需要构造堆并反复调整堆的是？','B','堆排序先建立初始堆，再反复交换堆顶与末尾元素并调整堆。'),
    ('00000000-0000-0000-0000-000000020007','DATA_STRUCTURE','DS_GRAPH','MEDIUM','有 n 个顶点的强连通有向图，至少需要多少条有向边？','A','n 个顶点构成一个有向环即可强连通，因此至少需要 n 条有向边。'),
    ('00000000-0000-0000-0000-000000020008','DATA_STRUCTURE','DS_GRAPH','HARD','在有向图中加入一条跨强连通分量的边，最可能带来的变化是？','D','若新边与原有路径形成回路，多个强连通分量可能合并，因此强连通分量数量可能减少。'),

    ('00000000-0000-0000-0000-000000020009','COMPUTER_ORGANIZATION','CO_NUMBER','BASIC','若无符号整数采用 8 位二进制表示，则最大可表示的十进制数是？','C','8 位无符号整数范围为 0 到 2^8 - 1，即 255。'),
    ('00000000-0000-0000-0000-000000020010','COMPUTER_ORGANIZATION','CO_CACHE','MEDIUM','DDR 存储器在时钟上升沿和下降沿都传输数据，这体现了哪一特点？','B','DDR 的含义是双倍数据率，即一个时钟周期内可在两个边沿传输数据。'),
    ('00000000-0000-0000-0000-000000020011','COMPUTER_ORGANIZATION','CO_CACHE','MEDIUM','用若干 8K × 8 位芯片组成 32K × 32 位存储器，通常需要多少片芯片？','D','字长从 8 位扩展到 32 位需要 4 片并联，容量从 8K 扩展到 32K 需要 4 组，共 16 片。'),
    ('00000000-0000-0000-0000-000000020012','COMPUTER_ORGANIZATION','CO_CPU','MEDIUM','五段流水线中，lw 指令的数据 Cache 缺失通常在哪个阶段检测到？','C','lw 指令的数据访存发生在 MEM 阶段，因此数据 Cache 缺失通常在存储器访问阶段检测到。'),
    ('00000000-0000-0000-0000-000000020013','COMPUTER_ORGANIZATION','CO_CPU','HARD','五段流水线不采用转发时，紧邻的 RAW 数据相关通常需要通过什么方式解决？','A','没有转发时，后继指令必须等待前驱指令写回寄存器，常通过插入 nop 或暂停周期解决。'),
    ('00000000-0000-0000-0000-000000020014','COMPUTER_ORGANIZATION','CO_INSTRUCTION','MEDIUM','相对寻址形成有效地址时，通常使用哪一寄存器内容作为基准？','B','相对寻址通常以程序计数器 PC 的内容加位移量得到目标地址。'),
    ('00000000-0000-0000-0000-000000020015','COMPUTER_ORGANIZATION','CO_IO','BASIC','主机与外设之间通常通过哪类部件完成控制和状态转换？','C','I/O 接口或外设控制器负责在主机总线与外设之间进行控制、状态和数据转换。'),
    ('00000000-0000-0000-0000-000000020016','COMPUTER_ORGANIZATION','CO_IO','HARD','多重中断系统中，响应优先级和处理优先级的关系正确的是？','D','响应优先级决定多个请求同时到达时先响应谁，处理优先级决定中断服务程序能否被更高处理优先级中断打断。'),

    ('00000000-0000-0000-0000-000000020017','OPERATING_SYSTEM','OS_PROCESS','BASIC','成功创建进程后，该进程通常首先进入哪种状态？','B','创建原语完成后，进程具备被调度的条件，通常进入就绪队列等待 CPU。'),
    ('00000000-0000-0000-0000-000000020018','OPERATING_SYSTEM','OS_PROCESS','MEDIUM','高优先级进程抢占正在运行的低优先级进程后，低优先级进程通常转为？','C','被抢占的进程仍具备运行条件，只是失去 CPU，因此转入就绪态。'),
    ('00000000-0000-0000-0000-000000020019','OPERATING_SYSTEM','OS_DEADLOCK','HARD','某类互斥资源数量不足，多个进程按相同顺序多次申请资源时，系统可能出现什么风险？','A','若进程持有部分资源并继续请求其他资源，且资源不足，就可能形成等待环并导致死锁。'),
    ('00000000-0000-0000-0000-000000020020','OPERATING_SYSTEM','OS_MEMORY','MEDIUM','共享段表中的共享计数通常用于表示什么？','D','共享计数记录当前有多少进程共享该段，计数为 0 时系统才可回收该段。'),
    ('00000000-0000-0000-0000-000000020021','OPERATING_SYSTEM','OS_FILE','MEDIUM','FAT 文件系统中引入“簇”作为分配单位，主要目的是什么？','B','以簇为单位可减少 FAT 表项数量，降低 FAT 表占用空间和访问开销。'),
    ('00000000-0000-0000-0000-000000020022','OPERATING_SYSTEM','OS_IO','BASIC','设备驱动程序主要位于哪两者之间，完成通信和转换？','A','设备驱动程序位于请求 I/O 的进程和设备控制器之间，屏蔽具体设备差异。'),
    ('00000000-0000-0000-0000-000000020023','OPERATING_SYSTEM','OS_IO','MEDIUM','SPOOLing 技术可以把独占设备改造成逻辑共享设备，核心依赖通常是？','C','SPOOLing 借助磁盘上的输入井、输出井和后台进程实现缓冲与排队。'),
    ('00000000-0000-0000-0000-000000020024','OPERATING_SYSTEM','OS_FILE','HARD','磁盘顺序处理记录时，合理调整记录在磁道上的排列主要是为了减少什么？','D','如果处理时间与旋转位置不匹配，下一条记录可能刚错过磁头；优化排列可减少旋转等待。'),

    ('00000000-0000-0000-0000-000000020025','COMPUTER_NETWORK','CN_PHYSICAL','MEDIUM','信道中的“传播时延”主要取决于什么？','B','传播时延等于链路长度除以信号传播速率，与报文长度无直接关系。'),
    ('00000000-0000-0000-0000-000000020026','COMPUTER_NETWORK','CN_PHYSICAL','HARD','链路上同时存在的比特数量可近似由什么计算？','C','链路上的比特数量约等于传播时延乘以数据传输率，也称带宽时延积。'),
    ('00000000-0000-0000-0000-000000020027','COMPUTER_NETWORK','CN_DATA_LINK','MEDIUM','选择重传 SR 协议中，4 位序号空间下接收窗口通常不能超过多少？','B','SR 为避免新旧帧混淆，发送窗口和接收窗口通常不超过序号空间的一半；4 位序号空间为 16，因此窗口不超过 8。'),
    ('00000000-0000-0000-0000-000000020028','COMPUTER_NETWORK','CN_NETWORK','MEDIUM','IP 数据报分片后，目的主机重组分片主要依据哪些字段？','A','重组依赖源/目的地址、协议、标识字段、片偏移和 MF 标志等信息。'),
    ('00000000-0000-0000-0000-000000020029','COMPUTER_NETWORK','CN_DATA_LINK','BASIC','ARP 请求报文在同一广播域内通常以什么方式发送？','D','ARP 请求需要询问目标 IP 对应的 MAC 地址，因此通常以广播帧发送。'),
    ('00000000-0000-0000-0000-000000020030','COMPUTER_NETWORK','CN_TRANSPORT','MEDIUM','在 TCP/IP 网络中，分组乱序到达后的排序通常由哪一层处理？','C','IP 层尽力交付不保证顺序，TCP 通过序号对字节流进行重排。'),
    ('00000000-0000-0000-0000-000000020031','COMPUTER_NETWORK','CN_TRANSPORT','HARD','TCP 中用于避免连接释放后旧报文影响新连接的计时器是？','B','时间等待计时器对应 TIME-WAIT 状态，可保证旧连接报文在网络中消失。'),
    ('00000000-0000-0000-0000-000000020032','COMPUTER_NETWORK','CN_APPLICATION','MEDIUM','HTTP/1.1 持续连接的主要优势是？','A','持续连接可以在同一个 TCP 连接上传输多个请求和响应，减少连接建立开销。')
) AS q(id, subject_code, chapter_code, difficulty, stem, answer, explanation)
JOIN subjects s ON s.code = q.subject_code
JOIN chapters c ON c.code = q.chapter_code;

