    ('00000000-0000-0000-0000-000000020001','DS_LINEAR_LIST_BASIC'),('00000000-0000-0000-0000-000000020002','DS_TREE_TRAVERSAL'),('00000000-0000-0000-0000-000000020003','DS_TREE_TRAVERSAL'),('00000000-0000-0000-0000-000000020004','DS_TREE_TRAVERSAL'),('00000000-0000-0000-0000-000000020005','DS_SORT_COMPLEXITY'),('00000000-0000-0000-0000-000000020006','DS_SORT_COMPLEXITY'),('00000000-0000-0000-0000-000000020007','DS_GRAPH_TRAVERSAL'),('00000000-0000-0000-0000-000000020008','DS_GRAPH_TRAVERSAL'),
