INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000020701','资料文档改写'),
    ('00000000-0000-0000-0000-000000020702','王道八套卷')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000020001'),('00000000-0000-0000-0000-000000020002'),('00000000-0000-0000-0000-000000020003'),('00000000-0000-0000-0000-000000020004'),('00000000-0000-0000-0000-000000020005'),('00000000-0000-0000-0000-000000020006'),('00000000-0000-0000-0000-000000020007'),('00000000-0000-0000-0000-000000020008'),
    ('00000000-0000-0000-0000-000000020009'),('00000000-0000-0000-0000-000000020010'),('00000000-0000-0000-0000-000000020011'),('00000000-0000-0000-0000-000000020012'),('00000000-0000-0000-0000-000000020013'),('00000000-0000-0000-0000-000000020014'),('00000000-0000-0000-0000-000000020015'),('00000000-0000-0000-0000-000000020016'),
    ('00000000-0000-0000-0000-000000020017'),('00000000-0000-0000-0000-000000020018'),('00000000-0000-0000-0000-000000020019'),('00000000-0000-0000-0000-000000020020'),('00000000-0000-0000-0000-000000020021'),('00000000-0000-0000-0000-000000020022'),('00000000-0000-0000-0000-000000020023'),('00000000-0000-0000-0000-000000020024'),
    ('00000000-0000-0000-0000-000000020025'),('00000000-0000-0000-0000-000000020026'),('00000000-0000-0000-0000-000000020027'),('00000000-0000-0000-0000-000000020028'),('00000000-0000-0000-0000-000000020029'),('00000000-0000-0000-0000-000000020030'),('00000000-0000-0000-0000-000000020031'),('00000000-0000-0000-0000-000000020032')
) AS q(id)
JOIN question_tags tag ON tag.name IN ('选择题扩容', '资料文档改写', '王道八套卷')
WHERE NOT EXISTS (
    SELECT 1 FROM question_tag_relations existing
    WHERE existing.question_id = CAST(q.id AS UUID)
      AND existing.tag_id = tag.id
);
